function describe(value: boolean | string): string {
  // TODO: narrow with typeof, then handle each case
  return String(value);
}

console.log(describe(true));
console.log(describe('hello'));

solution.code:
function describe(value: boolean | string): string {
  if (typeof value === 'boolean') {
    return value ? 'yes' : 'no';
  }
  return String(value.length);
}

console.log(describe(true));
console.log(describe('hello'));

