function shout(id: string | number): string {
  // toUpperCase exists on string but NOT on number
  return (id as any).toUpperCase();
}

console.log(shout('abc'));
console.log(shout(42)); // crashes: 42..toUpperCase is not a function

solution.code:
function shout(id: string | number): string {
  if (typeof id === 'string') {
    return id.toUpperCase();
  }
  return id.toString();
}

console.log(shout('abc'));
console.log(shout(42));

type Shape =
  | { kind: 'circle'; radius: number }
  | { kind: 'square'; side: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case 'circle':
      return Math.PI * shape.radius ** 2;
    case 'square':
      return shape.side ** 2;
    default: {
      const _exhaustive: never = shape;
      return _exhaustive;
    }
  }
}

console.log(area({ kind: 'square', side: 3 }));
console.log(area({ kind: 'circle', radius: 1 }).toFixed(2));
